// One nudge per breached conversation. The notification's dedupe key is namespaced
// per SLA multiple, so the owner is chased again as it gets worse rather than every
// five minutes forever — an alert that repeats identically is an alert people mute.
const rows = $input.first().json;
if (!Array.isArray(rows) || rows.length === 0) return [];

return rows.map((row) => ({
  json: {
    business_id: row.business_id,
    conversation_id: row.conversation_id,
    waiting_minutes: row.waiting_minutes,
    dedupe_key: `sla_breach:${row.conversation_id}:${Math.floor(row.waiting_minutes / 30)}`,
    body: `A conversation has been waiting ${row.waiting_minutes} minutes for a person (${(row.handover_reason_code || 'escalated').replace(/_/g, ' ')}).`,
  },
}));
